{
  "description": "The creature is shown in right-facing profile standing on a flat surface. It has the overall body shape, fur, and head of a large brown bear, but its back, sides, shoulders, hips and lower legs are covered in glossy, dark brown to black segmented armor resembling a beetle's exoskeleton, with a lighter tan segmented underside and neck. A single long, curved, glossy black horn with a small inner tooth projects from the forehead. The animal stands on four thick legs ending in clawed paws and has a short furry tail tipped with a pointed plate. The armor is highly reflective with overlapping plates and small circular pits along the edges.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a brown bear head with dense brown fur, a paler tan muzzle, a black nose, small brown eyes, and fine whiskers on the muzzle",
      "where": "at the anterior end of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "a single large, smooth, glossy black horn that curves strongly upward and backward, with a small pointed notch on its inner curve and a broad base fused to the forehead",
      "where": "arising from the midline of the forehead between the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry brown ears with dense fur",
      "where": "on top of the head just behind the base of the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular legs covered in brown fur, each with large glossy dark plates over the upper thigh/shoulder and segmented greaves over the lower leg, the front greaves bearing small spikes on the rear edge",
      "where": "under the body, two forelegs and two hindlegs supporting the trunk"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with brown fur and five long, curved, dark claws on each",
      "where": "at the distal ends of the four legs in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a short, furry brown tail with a small, pointed, dark glossy plate at the tip",
      "where": "at the posterior end of the body, projecting slightly downward"
    },
    {
      "part": "shell",
      "looks_like": "a large, domed, glossy dark brown to black dorsal shell made of overlapping transverse segments with a large smooth shoulder shield and small circular rivet-like pits along the lower margin",
      "where": "covering the back from the rear of the neck to the base of the tail"
    },
    {
      "part": "plates",
      "looks_like": "additional glossy dark plates on the shoulders, hips and as segmented greaves on the legs, and lighter tan, ribbed, segmented plates with circular pits on the underside of the trunk and in rings around the lower neck",
      "where": "on the sides of the shoulders and hips, encircling the lower legs, lining the ventral trunk, and forming concentric bands around the throat"
    }
  ],
  "attached_objects": [],
  "animals": ["bear", "beetle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
